python3 -c "
import json

with open('/app/resources/treasury_bulletin_1992_03.json') as f:
    data = json.load(f)

# Find figure elements around page 148
for i, elem in enumerate(data['document']['elements']):
    if elem.get('type') == 'figure':
        bbox = elem.get('bbox', [])
        if bbox:
            page = bbox[0].get('page_id')
            if page in [147, 148, 149]:
                print(f'Element {i}: page {page}')
                content = elem.get('content')
                print('Content type:', type(content))
                if content:
                    if isinstance(content, str):
                        print('Content:', content[:500])
                    elif isinstance(content, dict):
                        print('Content keys:', content.keys())
                print('---')
"
